questionvariables.text:
kgrp(n) := block([s, out, k], s: string(n), k: slength(s), if k < 5 then s else (out: "", while k > 3 do (out: sconcat("\\,", substring(s, k-2, k+1), out), k: k-3), sconcat(substring(s, 1, k+1), out)));
ksh(v) := block([c, w, f], c: floor(100*v+1/2), w: floor(c/100), f: c-100*w, if f = 0 then kgrp(w) else sconcat(kgrp(w), ".", if f < 10 then "0" else "", string(f)));
dd(v) := if integerp(v) then v else if integerp(10*v) then dispdp(float(v),1) else if integerp(100*v) then dispdp(float(v),2) else if integerp(1000*v) then dispdp(float(v),3) else dispdp(float(v),4);
ix: 1+rand(10);
/* Design: construct-an-example pattern. [P, n]. Valid rates: 1 - 2^(-1/n) < r/100 <= 1 - 2^(-1/(n-1)). tmid, tfast, tslow: test inputs by n. Source: original. */
L: [[240000,3],[96000,4],[1800000,5],[450000,6],[75000,3],[3200000,4],[128000,5],[680000,6],[52000,4],[900000,5]];
E: L[ix];
P: E[1]; n: E[2];
half: P/2;
tmid: if n=3 then 25 elseif n=4 then 18.3 elseif n=5 then 14.4 else 11.9;
tfast: if n=3 then 31.3 elseif n=4 then 22.6 elseif n=5 then 17.9 else 14.9;
tslow: if n=3 then 18.6 elseif n=4 then 13.9 elseif n=5 then 10.9 else 8.9;
vt: P*(1-tmid/100)^n;
vtm: P*(1-tmid/100)^(n-1);

feedbackvariables.text:
vn: P*(1-ansr/100)^n;
vm: P*(1-ansr/100)^(n-1);
okr: is(ansr>0 and ansr<100 and vn<P/2 and vm>=P/2);
bad: is(ansr<=0 or ansr>=100);
fast: is(vm<P/2);
